import{_ as s,o as a,c as e,a2 as l}from"./chunks/framework.RycU2wFZ.js";const h=JSON.parse('{"title":"AgentFinOps 企业控制台操作指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console_guide.md","filePath":"guide/console_guide.md"}'),o={name:"guide/console_guide.md"};function t(i,n,p,r,c,g){return a(),e("div",null,[...n[0]||(n[0]=[l(`<h1 id="agentfinops-企业控制台操作指南" tabindex="-1">AgentFinOps 企业控制台操作指南 <a class="header-anchor" href="#agentfinops-企业控制台操作指南" aria-label="Permalink to &quot;AgentFinOps 企业控制台操作指南&quot;">​</a></h1><blockquote><p><strong>适用用户</strong>：企业管理员、财务主管、开发团队负责人<br><strong>控制台地址</strong>：<code>https://console.aipmedia.cn</code> (生产环境) / <code>http://localhost:5173</code> (本地开发)</p></blockquote><hr><h2 id="_1-控制台核心功能模块" tabindex="-1">1. 控制台核心功能模块 <a class="header-anchor" href="#_1-控制台核心功能模块" aria-label="Permalink to &quot;1. 控制台核心功能模块&quot;">​</a></h2><p>AgentFinOps 控制台是企业管理平面与运营中心，提供全方位的 AI Agent 行为审计与财务治理能力：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        AgentFinOps 企业管理控制台                      │</span></span>
<span class="line"><span>├───────────────────┬────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 1. 组织与团队治理 │ • 租户基本设置与成员 RBAC 权限体系 (Owner/Admin/Dev)│</span></span>
<span class="line"><span>│                   │ • 事业群 / 部门树状层级创建与月度预算划拨          │</span></span>
<span class="line"><span>│                   │ • 项目组与智能体 (Agent) 资产归集                  │</span></span>
<span class="line"><span>├───────────────────┼────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 2. API Key 与凭证 │ • Agent 专用 API Key 签发、失效与自动轮转          │</span></span>
<span class="line"><span>│                   │ • 作用域权限细粒度限制与白名单域名绑定             │</span></span>
<span class="line"><span>├───────────────────┼────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 3. 协同审批 (HITL)│ • 飞书 / 企业微信 / 钉钉通知机器人与 Webhook 配置  │</span></span>
<span class="line"><span>│                   │ • 三级风控阈值自定义 (免审额度 / 审批额度 / 硬顶) │</span></span>
<span class="line"><span>│                   │ • 审批单在线历史回溯与决议流水                     │</span></span>
<span class="line"><span>├───────────────────┼────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 4. 财务与账本中心 │ • 虚拟钱包实时余额与冻结池监控                     │</span></span>
<span class="line"><span>│                   │ • 微信 / 支付宝聚合充值收银台与对公打款审核        │</span></span>
<span class="line"><span>│                   │ • 只追加不可变账本明细与月度数电发票申请导出       │</span></span>
<span class="line"><span>├───────────────────┼────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 5. 审计与全链路排查│ • Agent 行为黑匣子时间线 (Timeline) 毫秒级复现     │</span></span>
<span class="line"><span>│                   │ • Langfuse 联动徽标一键直达 Trace 详情页           │</span></span>
<span class="line"><span>└───────────────────┴────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-核心操作流程" tabindex="-1">2. 核心操作流程 <a class="header-anchor" href="#_2-核心操作流程" aria-label="Permalink to &quot;2. 核心操作流程&quot;">​</a></h2><h3 id="_2-1-步骤一-创建部门与配置多级预算" tabindex="-1">2.1 步骤一：创建部门与配置多级预算 <a class="header-anchor" href="#_2-1-步骤一-创建部门与配置多级预算" aria-label="Permalink to &quot;2.1 步骤一：创建部门与配置多级预算&quot;">​</a></h3><ol><li>登录控制台，进入左侧导航 <strong>「组织与部门」</strong>；</li><li>点击 <strong>「新建部门」</strong>，输入部门名称（如“智能客服事业部”）与负责人联系方式；</li><li>为该部门划拨 <strong>月度预算额度（如 ¥20,000）</strong>；</li><li>当部门下辖所有 Agent 累计消耗达到预算 80% 时，系统自动向负责人推送预警；达到 100% 时自动开启熔断阻断。</li></ol><h3 id="_2-2-步骤二-接入飞书-企业微信审批机器人" tabindex="-1">2.2 步骤二：接入飞书 / 企业微信审批机器人 <a class="header-anchor" href="#_2-2-步骤二-接入飞书-企业微信审批机器人" aria-label="Permalink to &quot;2.2 步骤二：接入飞书 / 企业微信审批机器人&quot;">​</a></h3><ol><li>进入左侧导航 <strong>「安全与审批 (HITL)」</strong> $\\to$ <strong>「审批通道配置」</strong>；</li><li>选择 <strong>飞书（Feishu）</strong> 或 <strong>企业微信（WeCom）</strong>；</li><li>填入企业机器人的 <code>Webhook URL</code> 与 <code>Secret</code>；</li><li>配置审批触发阈值： <ul><li><strong>自动放行上限</strong>：例如 $\\le 1.00$ 元；</li><li><strong>人工审批阈值</strong>：大于 $1.00$ 元且 $\\le 100.00$ 元；</li><li><strong>单笔硬阻断上限</strong>：大于 $100.00$ 元。</li></ul></li></ol><h3 id="_2-3-步骤三-财务充值与对账单导出" tabindex="-1">2.3 步骤三：财务充值与对账单导出 <a class="header-anchor" href="#_2-3-步骤三-财务充值与对账单导出" aria-label="Permalink to &quot;2.3 步骤三：财务充值与对账单导出&quot;">​</a></h3><ol><li>进入 <strong>「财务中心」</strong> $\\to$ <strong>「钱包与充值」</strong>；</li><li>选择充值金额（如 ¥5,000），页面动态生成<strong>微信支付 / 支付宝收款码</strong>；</li><li>扫码支付完成后，账务中心通过 Webhook 毫秒级原子入账，系统按 6 位微单位换算到企业虚拟账本；</li><li>月末可在 <strong>「财务账单」</strong> 中一键导出按部门拆分的对账 CSV 清单，并直连数电发票系统开具增值税专票。</li></ol>`,14)])])}const u=s(o,[["render",t]]);export{h as __pageData,u as default};
